  bilingual: [['Birth rate', 'Le taux de natalité'], ['Death rate', 'Le taux de mortalité'], ['Growth rate', 'Le taux de croissance'], ['Doubling time', 'Le temps de doublement'], ['Population projection', 'La projection démographique'], ['Fecundity', 'La fertilité biologique (fécondabilité)']],
